import {expect, test} from 'vitest';
import {renderToString} from 'react-dom/server';

import {AppThemeProvider} from './theme/AppThemeProvider';
import {App} from './App';

for (const theme of ['light', 'dark', 'system'] as const) {
    test(`renders with ${theme} selected`, () => {
        const html = renderToString(
            <AppThemeProvider defaultTheme={theme}>
                <App />
            </AppThemeProvider>,
        );
        const inputs = [...html.matchAll(/<input[^>]*value="(light|dark|system)"[^>]*>/g)].map((m) => ({
            value: m[1],
            checked: m[0].includes('checked'),
        }));
        console.log(theme, JSON.stringify(inputs), 'resolved:', html.match(/применено:.*?<\/span>/)?.[0]);
